<?php
namespace App\Http\Controllers\Admin;
use App\Actions\Payments\CapturePayment;use App\Actions\Payments\SyncPaymentStatus;use App\Http\Controllers\Controller;use App\Models\Payment;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;
class PaymentController extends Controller { public function capture(Request $r,Payment $payment,CapturePayment $action):RedirectResponse{abort_unless($r->user()->can('payments.capture'),403);$d=$r->validate(['provider_reference'=>'required|string|max:191','amount'=>'required|decimal:0,2|min:0','currency'=>'required|in:IDR']);$action->execute($payment,$d['provider_reference'],$d['amount'],$d['currency']);return back()->with('status','Payment terverifikasi dan ledger diposting.');}public function sync(Request $r,Payment $payment,SyncPaymentStatus $action):RedirectResponse{abort_unless($r->user()->can('payments.reconcile'),403);$action->execute($payment,$r->user());return back()->with('status','Status payment telah direkonsiliasi dengan Midtrans.');} }
